-- CAB-0013: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'CAB-0013: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'CAB-0013: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('steven-sim-chee-keong','noraini-ahmad') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0013: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('bukit mertajam','parit sulong') and slug not in ('steven-sim-chee-keong','noraini-ahmad')) then raise exception 'CAB-0013: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0013:%' and (m.source_type <> 'editorial' or e.slug not in ('steven-sim-chee-keong','noraini-ahmad') or m.import_key not like 'CAB-0013:' || e.slug || ':%')) then raise exception 'CAB-0013: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'steven-sim-chee-keong','Steven Sim Chee Keong','government','Minister of Entrepreneur and Cooperatives Development','Bukit Mertajam','Pulau Pinang','Steven Sim Chee Keong is Minister of Entrepreneur and Cooperatives Development. He represents Bukit Mertajam, Pulau Pinang, in the Dewan Rakyat. He is a member of DAP.','https://www.kuskop.gov.my/','/portraits/steven-sim-chee-keong.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P045.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Bukit Mertajam", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4084"}, {"label": "DAP · current leadership", "url": "https://dapmalaysia.org/en/our-leaders/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'noraini-ahmad','Noraini Ahmad','government','Minister of Plantation and Commodities','Parit Sulong','Johor','Noraini Ahmad is Minister of Plantation and Commodities. She represents Parit Sulong, Johor, in the Dewan Rakyat. She is a member of UMNO.','https://www.kpk.gov.my/','/portraits/noraini-ahmad.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P147.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Parit Sulong", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4186"}, {"label": "UMNO · 2023–2026 supreme council", "url": "https://umno-online.my/wp-content/uploads/2026/01/Senarai-MKT-2023-2026-update-Januari-2026-jan-2026-final.pdf"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('steven-sim-chee-keong','noraini-ahmad') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0013: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0013:steven-sim-chee-keong:pks-bursa-200-2030','Help 200 high-potential SMEs list on Bursa Malaysia by 2030','Economy',null,null,'2030-12-31','2026-06-04','https://bernama.com/en/news.php/world/crime_courts/target%3D%27_blank%27?id=2564638',null,null,'Steven said PKS@BURSA would build a pipeline to help 200 high-potential small and medium enterprises seek listing by 2030.','The statement establishes the programme target and financing support. Allocated funding and eligible loan amounts do not establish that 200 firms have listed. A verified listing count and outcome status were not established.','2026-11-09','editorial',false from public.entities e where e.slug='steven-sim-chee-keong' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0013:steven-sim-chee-keong:scale-sme-definition-2027','Review the national SME definition under SCALE 2027','Economy',null,null,'2027-12-31','2026-10-22','https://web26.bernama.com/en/region/news.php?id=2624266',null,null,'Steven announced that KUSKOP would review the SME definition in place since 2013 as a priority of the SCALE Action Plan for 2027.','The announcement describes the intended review and its purpose. A revised definition taking effect was not verified. The launch of an action plan is not treated as delivery of the definition reform.','2026-11-09','editorial',false from public.entities e where e.slug='steven-sim-chee-keong' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0013:noraini-ahmad:oil-palm-smallholder-replanting','Strengthen support for smallholder oil-palm replanting','Economy','in_progress',null,null,'2026-09-24','https://bernama.com/en/news.php?id=2611208','2026-09-24','https://bernama.com/en/news.php?id=2611208','Noraini said her ministry and MPOB would support replacement of ageing oil palms through replanting assistance, including TSPKS.','She described assistance being implemented for smallholders. MSPO-certified hectares and the RM63.5 million market-support allocation are different measures, not completed replanted hectares. No target-specific completed area, overall deadline or numerical completion was established.','2026-11-09','editorial',false from public.entities e where e.slug='noraini-ahmad' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

